input.command:
cd /workspace/dataset && rep() { local n=$1 c=$2 s=""; for ((i=0;i<n;i++)); do s+="$c"; done; printf '%s' "$s"; }
echo "=== 2-byte codepoints (é = 0xC3 0xA9), N codepoints = 2N bytes ==="
for n in 31 32 33 63 64 127 128 129; do s=$(rep $n 'é'); printf 'e-acute x%-4s (cp=%s bytes=%s) -> %s\n' "$n" "$n" "$(printf '%s' "$s" | wc -c)" "$(./test4_executable "$s" | tr '\n' ',')"; done
